import jwt

# This class exists to make the session work in a predictable manner
class Session:
    def __init__(self, redis_client, sid):
        self._r = redis_client
        self._sid = sid
        self._new = False
        self._token = None

    def get(self, key):
        val = self._r.hget('session.'+self._sid, key)
        if val is None:
            self._new = True
        return val

    def __setattr__(self, name, value):
        if not name.startswith('_'):
            self.__setitem__(name, value)
        else:
            super().__setattr__(name, value)

    def __getattr__(self, name):
        if not name.startswith('_'):
            return self.__getitem__(name)
        else:
            return super().__getattr__(name)

    def __delitem__(self, name):
        return self._r.hdel('session.'+self._sid, name)

    def __getitem__(self, key):
        return int(self.get(key))

    def __setitem__(self, key, item):
        self._r.hset('session.'+self._sid, key, item)

    def encode(self):
        return jwt.encode(
            {'sid': self._sid},
            self._r.get('session.'+self._sid+'.key'),
            algorithm='HS256'
        )

    def decode(self, token):
        try:
            jwt.decode(
                token,
                self._r.get('session.'+self._sid+'.key'),
                algorithms=['HS256']
            )
        except:
            self._new = True
            self._token = token

class SessionProxy:
    def __init__(self, g, redis_client):
        self._g = g
        self._r = redis_client

    def get(self, key):
        if hasattr(self._g, 'session'):
            return self._g.session[key]
        return None

