def calc_odds():
    a_sum = int(rclient.get('race.a.money') or 0)
    b_sum = int(rclient.get('race.b.money') or 0)
    if a_sum == 0:
        a_sum = 1
    if b_sum == 0:
        b_sum = 1

    a_odds = a_sum / float(b_sum)
    b_odds = b_sum / float(a_sum)

    return a_odds, b_odds, a_sum, b_sum

@app.route('/check')
@user
def get_money():
    now = int(time.time())
    start = int(rclient.get('start') or 0)
    if start == 0:
        reset()

    if now > start:
        a_odds, b_odds, a_sum, b_sum = calc_odds()
    else:
        a_odds, b_odds, a_sum, b_sum = 0,0,0,0

    uid = session.uid

    payouts = rclient.lrange('payouts.'+uid, 0, -1)
    if payouts:
        for p in payouts:
            session.money += int(float(p))
        rclient.delete('payouts.'+uid)
    if session.money < 100:
        session.money = 100

    side = None
    bet = rclient.hget('race.a.bets', uid)
    if bet:
        side = 0
    else:
        bet = rclient.hget('race.b.bets', uid)
        if bet:
            side = 1

    return jsonify(
        a=a_odds, b=b_odds,
        a_sum=a_sum, b_sum=b_sum,
        bet=bet,
        side=side,
        money=session.money,
        start=start
    )

