import requests
import time
import json

def get_status():
    r = requests.get('http://localhost:8000/check')
    return r.json()

def place_bet(winner, amount):
    data = {'bet': str(amount)}
    r = requests.patch(f'http://localhost:8000/bet/{winner}', data=data)
    return r.json()

def get_snails():
    r = requests.get('http://localhost:8000/snails')
    return r.json()

def mark_win(winner):
    r = requests.get(f'http://localhost:8000/win/{winner}')
    return r.json()

def main():
    while True:
        status = get_status()
        money = status['money']
        print(f"Current money: {money}")

        if money >= 250000:
            print("Reached target amount!")
            break

        snails = get_snails()
        time.sleep(2)  # Wait for betting period

        # Place bet on snail with better odds
        status = get_status()
        if status['a'] > status['b']:
            winner = 0
        else:
            winner = 1

        bet_amount = min(money, 1000000)
        place_bet(winner, bet_amount)

        # Wait for race to finish
        time.sleep(12)

        # Mark our predicted winner
        mark_win(winner)
        time.sleep(2)

if __name__ == '__main__':
    main()
